// Generates Go data tables from pinned cldr-json (CLDR 48.0).
// Output: ../../cldr_plural_data.go (+ number/date data in later stages).
import { readFileSync, writeFileSync } from 'node:fs';

const CLDR_VERSION = JSON.parse(readFileSync('node_modules/cldr-core/package.json')).version;

function loadPlural(kind) {
  const file = kind === 'cardinal' ? 'plurals.json' : 'ordinals.json';
  const j = JSON.parse(readFileSync(`node_modules/cldr-core/supplemental/${file}`));
  return j.supplemental[`plurals-type-${kind}`];
}

function stripSamples(rule) {
  // remove @integer/@decimal sample suffixes
  return rule.replace(/@integer[^@]*|@decimal[^@]*/g, '').trim();
}

function emitPluralMap(name, data) {
  const locales = Object.keys(data).sort();
  let out = `var ${name} = map[string]map[string]string{\n`;
  for (const loc of locales) {
    const rules = data[loc];
    const entries = Object.entries(rules)
      .map(([k, v]) => [k.replace('pluralRule-count-', ''), stripSamples(v)])
      .filter(([, v]) => v !== '');
    if (!entries.length) continue;
    out += `\t${JSON.stringify(loc)}: {${entries.map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`).join(', ')}},\n`;
  }
  return out + '}\n\n';
}

let src = `// Code generated by testdata/gen/gen-cldr.mjs from CLDR ${CLDR_VERSION}. DO NOT EDIT.
// Provenance: cldr-core@${CLDR_VERSION} (cldr-json project, Unicode CLDR 48.0).
package messageformat

`;
src += emitPluralMap('cldrCardinalRules', loadPlural('cardinal'));
src += emitPluralMap('cldrOrdinalRules', loadPlural('ordinal'));
writeFileSync('../../cldr_plural_data.go', src);
const card = loadPlural('cardinal'), ord = loadPlural('ordinal');
console.log(`CLDR ${CLDR_VERSION}: cardinal locales ${Object.keys(card).length}, ordinal locales ${Object.keys(ord).length}, bytes ${src.length}`);
